+inline float kda_reduce_sum(at::vec::Vectorized<float> value) {
+  alignas(64) float values[at::vec::Vectorized<float>::size()];
+  value.store(values);
+  float sum = 0.f;
+  for (float element : values) {
+    sum += element;
